import '../../models/speaker_model.dart' show SpeakerType;

/// Structured, typed actions generated by the conversational AI Venue Assistant.
///
/// Principle:
/// Free-form text never directly mutates a draft.
/// All user instructions are translated into typed actions that modify
/// the [ReconstructionDraft] under explicit validation rules.
abstract class VenueAssistantAction {
  String get actionType;
  String get description;

  Map<String, dynamic> toJson();

  static VenueAssistantAction fromJson(Map<String, dynamic> json) {
    final type = json['actionType'] as String? ?? 'unknown';
    switch (type) {
      case 'set_row_count':
        return SetRowCountAction(json['count'] as int);
      case 'set_default_seats_per_row':
        return SetDefaultSeatsPerRowAction(json['count'] as int);
      case 'set_block_count':
        return SetBlockCountAction(json['count'] as int);
      case 'set_aisle_boundaries':
        return SetAisleBoundariesAction(
          (json['aisleAfterSeats'] as List<dynamic>)
              .map((e) => (e as num).toInt())
              .toList(),
        );
      case 'remove_aisle_boundary':
        return RemoveAisleBoundaryAction(json['seatNumber'] as int);
      case 'set_row_seat_count':
        return SetRowSeatCountAction(
          startRow: json['startRow'] as int,
          endRow: json['endRow'] as int,
          count: json['count'] as int,
        );
      case 'remove_seat':
        return RemoveSeatAction(
          row: json['row'] as String,
          seatNumber: json['seatNumber'] as int,
        );
      case 'adjust_screen_height':
        return AdjustScreenHeightAction(
          delta: (json['delta'] as num?)?.toDouble(),
          targetHeight: (json['targetHeight'] as num?)?.toDouble(),
        );
      case 'set_room_dimensions':
        return SetRoomDimensionsAction(
          width: (json['width'] as num?)?.toDouble(),
          length: (json['length'] as num?)?.toDouble(),
          height: (json['height'] as num?)?.toDouble(),
        );
      case 'set_speaker_placements':
        return SetSpeakerPlacementsAction(
          placement: json['placement'] as String,
          cabinetType: json['cabinetType'] != null
              ? SpeakerType.values.firstWhere(
                  (t) => t.name == json['cabinetType'],
                  orElse: () => SpeakerType.sideSurround,
                )
              : null,
        );
      case 'set_lighting_layout':
        return SetLightingLayoutAction(
          ceilingRows: json['ceilingRows'] as int?,
          ceilingLightsCount: json['ceilingLightsCount'] as int?,
        );
      case 'targeted_measurement_request':
        return TargetedMeasurementRequestAction(
          measurementType: json['measurementType'] as String,
          reason: json['reason'] as String,
        );
      case 'clarification_required':
        return ClarificationRequiredAction(
          question: json['question'] as String,
          options: (json['options'] as List<dynamic>? ?? [])
              .map((e) => e.toString())
              .toList(),
        );
      case 'undo':
        return UndoAction(
          undoneActionDescription: json['undoneActionDescription'] as String?,
        );
      case 'unrelated_query':
        return UnrelatedQueryAction(
          message: json['message'] as String? ??
              'This assistant is for configuring your theatre venue.',
        );
      default:
        return UnknownAction(json['rawInput'] as String? ?? '');
    }
  }
}

/// Sets the logical number of seating rows in the draft.
class SetRowCountAction extends VenueAssistantAction {
  final int count;

  SetRowCountAction(this.count);

  @override
  String get actionType => 'set_row_count';

  @override
  String get description => 'Set row count to $count';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'count': count,
      };
}

/// Sets the default seat count per row.
class SetDefaultSeatsPerRowAction extends VenueAssistantAction {
  final int count;

  SetDefaultSeatsPerRowAction(this.count);

  @override
  String get actionType => 'set_default_seats_per_row';

  @override
  String get description => 'Set default seats per row to $count';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'count': count,
      };
}

/// Sets the number of seating blocks (separated by aisles).
class SetBlockCountAction extends VenueAssistantAction {
  final int count;

  SetBlockCountAction(this.count);

  @override
  String get actionType => 'set_block_count';

  @override
  String get description => 'Set seating block count to $count';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'count': count,
      };
}

/// Specifies seats after which a vertical aisle runs (e.g. [4, 12]).
class SetAisleBoundariesAction extends VenueAssistantAction {
  final List<int> aisleAfterSeats;

  SetAisleBoundariesAction(this.aisleAfterSeats);

  @override
  String get actionType => 'set_aisle_boundaries';

  @override
  String get description =>
      'Set aisle boundaries after seat(s) ${aisleAfterSeats.join(', ')}';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'aisleAfterSeats': aisleAfterSeats,
      };
}

/// Removes a specific aisle boundary (e.g. aisle after seat 12).
class RemoveAisleBoundaryAction extends VenueAssistantAction {
  final int seatNumber;

  RemoveAisleBoundaryAction(this.seatNumber);

  @override
  String get actionType => 'remove_aisle_boundary';

  @override
  String get description => 'Remove aisle boundary after seat $seatNumber';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'seatNumber': seatNumber,
      };
}

/// Sets seat count for a specific range of rows (irregular seating).
class SetRowSeatCountAction extends VenueAssistantAction {
  final int startRow;
  final int endRow;
  final int count;

  SetRowSeatCountAction({
    required this.startRow,
    required this.endRow,
    required this.count,
  });

  @override
  String get actionType => 'set_row_seat_count';

  @override
  String get description =>
      'Set row seat count for rows $startRow–$endRow to $count seats';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'startRow': startRow,
        'endRow': endRow,
        'count': count,
      };
}

/// Removes a specific seat from a row (missing seat / architectural column gap).
class RemoveSeatAction extends VenueAssistantAction {
  final String row;
  final int seatNumber;

  RemoveSeatAction({
    required this.row,
    required this.seatNumber,
  });

  @override
  String get actionType => 'remove_seat';

  @override
  String get description => 'Remove seat $seatNumber from row $row';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'row': row,
        'seatNumber': seatNumber,
      };
}

/// Adjusts the screen elevation or height above floor.
class AdjustScreenHeightAction extends VenueAssistantAction {
  final double? delta;
  final double? targetHeight;

  AdjustScreenHeightAction({this.delta, this.targetHeight});

  @override
  String get actionType => 'adjust_screen_height';

  @override
  String get description => targetHeight != null
      ? 'Set screen height to ${targetHeight}m'
      : 'Adjust screen height by ${delta ?? 0.5}m';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'delta': delta,
        'targetHeight': targetHeight,
      };
}

/// Sets room dimensions in the draft.
class SetRoomDimensionsAction extends VenueAssistantAction {
  final double? width;
  final double? length;
  final double? height;

  SetRoomDimensionsAction({this.width, this.length, this.height});

  @override
  String get actionType => 'set_room_dimensions';

  @override
  String get description =>
      'Set room dimensions: ${[
        if (width != null) 'width: ${width}m',
        if (length != null) 'length: ${length}m',
        if (height != null) 'height: ${height}m',
      ].join(', ')}';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'width': width,
        'length': length,
        'height': height,
      };
}

/// Adds visual speaker placement indicators.
class SetSpeakerPlacementsAction extends VenueAssistantAction {
  final String placement;
  final SpeakerType? cabinetType;

  SetSpeakerPlacementsAction({
    required this.placement,
    this.cabinetType,
  });

  @override
  String get actionType => 'set_speaker_placements';

  @override
  String get description => 'Set visual speakers: $placement';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'placement': placement,
        'cabinetType': cabinetType?.name,
      };
}

/// Sets ceiling/architectural lighting layout.
class SetLightingLayoutAction extends VenueAssistantAction {
  final int? ceilingRows;
  final int? ceilingLightsCount;

  SetLightingLayoutAction({this.ceilingRows, this.ceilingLightsCount});

  @override
  String get actionType => 'set_lighting_layout';

  @override
  String get description =>
      'Set lighting layout (${ceilingRows != null ? '$ceilingRows rows' : ''}${ceilingLightsCount != null ? '$ceilingLightsCount lights' : ''})';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'ceilingRows': ceilingRows,
        'ceilingLightsCount': ceilingLightsCount,
      };
}

/// Explains or requests a targeted physical measurement when scale is unknown.
class TargetedMeasurementRequestAction extends VenueAssistantAction {
  final String measurementType;
  final String reason;

  TargetedMeasurementRequestAction({
    required this.measurementType,
    required this.reason,
  });

  @override
  String get actionType => 'targeted_measurement_request';

  @override
  String get description => 'Request physical measurement: $measurementType';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'measurementType': measurementType,
        'reason': reason,
      };
}

/// Clarification requested when the user instruction is ambiguous.
class ClarificationRequiredAction extends VenueAssistantAction {
  final String question;
  final List<String> options;

  ClarificationRequiredAction({
    required this.question,
    this.options = const [],
  });

  @override
  String get actionType => 'clarification_required';

  @override
  String get description => 'Clarification required: $question';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'question': question,
        'options': options,
      };
}

/// Reverts the most recent assistant draft mutation.
class UndoAction extends VenueAssistantAction {
  final String? undoneActionDescription;

  UndoAction({this.undoneActionDescription});

  @override
  String get actionType => 'undo';

  @override
  String get description => undoneActionDescription != null
      ? 'Undo: $undoneActionDescription'
      : 'Undo last change';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'undoneActionDescription': undoneActionDescription,
      };
}

/// Handled when the query is unrelated to venue configuration.
class UnrelatedQueryAction extends VenueAssistantAction {
  final String message;

  UnrelatedQueryAction({
    this.message = 'This assistant is for configuring your theatre venue.',
  });

  @override
  String get actionType => 'unrelated_query';

  @override
  String get description => 'Unrelated query';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'message': message,
      };
}

/// Fallback for unrecognized instruction text.
class UnknownAction extends VenueAssistantAction {
  final String rawInput;

  UnknownAction(this.rawInput);

  @override
  String get actionType => 'unknown';

  @override
  String get description => 'Unknown instruction: $rawInput';

  @override
  Map<String, dynamic> toJson() => {
        'actionType': actionType,
        'rawInput': rawInput,
      };
}
